 const [open, setOpen] = useState(false);
 const ref = useRef<HTMLDivElement>(null);

 useEffect(() => {
 const onDoc = (e: MouseEvent) => {
 if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
 };
 document.addEventListener("mousedown", onDoc);
 return () => document.removeEventListener("mousedown", onDoc);
 }, []);

 return (
 <div className="grc-sel" ref={ref} style={{ position: "relative" }}>
 {label ? <span className="grc-sel__label">{label}</span> : null}
 <button className="grc-sel__control" onClick={() => setOpen(o => !o)} aria-haspopup="listbox" aria-expanded={open}>
 {icon ? <Icon icon={icon as any} size="sm" /> : null}
 <span>{value}</span>
 <Icon icon="caret-down-outline" size="sm" />
 </button>
 {open ? (
 <div className="grc-menu" role="listbox">
 {options.map(opt => (
 <button
 key={opt}
 role="option"
 aria-selected={opt === value}
 className={`grc-menu__item ${opt === value ? "is-active" : ""}`}
 onClick={() => { onChange(opt); setOpen(false); }}
 >
 {opt === value ? <Icon icon="check-outline" size="sm" /> : <span style={{ width: 16 }} />}
 <span>{opt}</span>
 </button>
 ))}
 </div>
 ) : null}
 </div>
 );
}
