","// Overall GRC Posture — weighted composite model.
import type { Severity } from "../mockData";

export type PostureBand = "Healthy" | "Watch" | "High Concern" | "Critical";

export interface PostureWeights {
 risk: number;
 controls: number;
 regulatory: number;
 governance: number;
 internal: number;
 assurance: number;
 remediation: number;
}

// Configurable weighting model (sums to 1.0).
export const POSTURE_WEIGHTS: PostureWeights = {
 risk: 0.25,
 controls: 0.2,
 regulatory: 0.2,
 governance: 0.1,
 internal: 0.1,
 assurance: 0.1,
 remediation: 0.05
};

export interface PostureBandDef {
 band: PostureBand;
 min: number;
 max: number;
 severity: Severity;
}

export const POSTURE_BANDS: PostureBandDef[] = [
 { band: "Healthy", min: 85, max: 100, severity: "healthy" },
 { band: "Watch", min: 70, max: 84, severity: "watch" },
 { band: "High Concern", min: 50, max: 69, severity: "high" },
 { band: "Critical", min: 0, max: 49, severity: "critical" }
];

export function postureBand(score: number): PostureBandDef {
 return POSTURE_BANDS.find(b => score >= b.min && score <= b.max) || POSTURE_BANDS[3];
}

export interface PostureContributor {
 key: keyof PostureWeights;
 label: string;
 subScore: number; // 0-100
 weight: number;
 weighted: number; // subScore * weight
 trendDir: "up" | "down" | "flat";
 deltaPts: number;
}

const raw: Omit<PostureContributor, "weight" | "weighted">[] = [
 { key: "risk", label: "Enterprise Risk", subScore: 68.2, trendDir: "down", deltaPts: -4.1 },
 { key: "controls", label: "Internal Controls", subScore: 83.6, trendDir: "up", deltaPts: 2.7 },
 { key: "regulatory", label: "Regulatory", subScore: 86.4, trendDir: "flat", deltaPts: 0.4 },
 { key: "governance", label: "Governance", subScore: 88.1, trendDir: "up", deltaPts: 1.2 },
 { key: "internal", label: "Internal Compliance", subScore: 79.3, trendDir: "down", deltaPts: -1.6 },
 { key: "assurance", label: "Combined Assurance", subScore: 76.8, trendDir: "flat", deltaPts: 0.3 },
 { key: "remediation", label: "Remediation", subScore: 71.4, trendDir: "down", deltaPts: -2.4 }
];

export const POSTURE_CONTRIBUTORS: PostureContributor[] = raw.map(r => ({
 ...r,
 weight: POSTURE_WEIGHTS[r.key],
 weighted: +(r.subScore * POSTURE_WEIGHTS[r.key]).toFixed(2)
}));

export const OVERALL_POSTURE = {
 id: "posture",
 name: "Overall GRC Posture",
 score: 78,
 previousScore: 81,
 deltaPts: -3,
 trendDir: "down" as const,
 band: postureBand(78).band,
 severity: postureBand(78).severity,
 statusLabel: "WATCH",
 confidence: 92,
 history12m: [84, 83, 82, 82, 81, 80, 81, 80, 79, 81, 81, 78],
 contributors: POSTURE_CONTRIBUTORS,
 topNegative: { label: "Operational Risk", deltaPts: -4.1, detail: "KRIs up 12% over 30 days; approaching tolerance." },
 topPositive: { label: "Internal Controls", deltaPts: 2.7, detail: "Effectiveness improved to 91.3% after automation uplift." },
 weightsNote: "Weighted model: Risk 25% · Controls 20% · Regulatory 20% · Governance 10% · Internal 10% · Assurance 10% · Remediation 5%."
};
