 <TrendArrow dir="down" text={POSTURE.trend} />
 <span className="grc-dq-chip" title={`Data quality ${DATA_QUALITY.score}% · ${DATA_QUALITY.totalFlags} open flags`}>
 <StatusPill severity={dataQualitySeverity(DATA_QUALITY.score)} label={`Data Quality ${DATA_QUALITY.score}%`} size="sm" />
