 </div>
 </div>
 <div className="grc-hero__contrib">
 <div className="grc-hero__contrib-row">
 <span className="grc-contrib grc-contrib--up"><TrendArrow dir="up" /> Top gain: <b>{OVERALL_POSTURE.topPositive.label}</b> +{OVERALL_POSTURE.topPositive.deltaPts} pts</span>
 <span className="grc-contrib grc-contrib--down"><TrendArrow dir="down" /> Top drag: <b>{OVERALL_POSTURE.topNegative.label}</b> {OVERALL_POSTURE.topNegative.deltaPts} pts</span>
 </div>
 <div className="grc-hero__weights">
 {OVERALL_POSTURE.contributors.slice().sort((a, b) => b.weighted - a.weighted).slice(0, 4).map(c => (
 <span key={c.key} className="grc-weightpill" title={`${c.label}: sub-score ${c.subScore} × weight ${Math.round(c.weight * 100)}%`}>{c.label} · {Math.round(c.weight * 100)}%</span>
 ))}
 </div>
 </div>
 </Card>

 {/* AI Executive Brief */}
 <Card className="grc-aibrief">
 <span className="grc-aibrief__tag"><Icon icon="ai-sparkle-fill" size="sm" /> AI EXECUTIVE BRIEF</span>
 <p className="grc-aibrief__body">{AI_BRIEF.summary}</p>
 <ul className="grc-aibrief__list">
 {AI_BRIEF.signals.map((s, i) => <li key={i}>{s}</li>)}
 </ul>
 <p className="grc-aibrief__rec">{AI_BRIEF.recommendation}</p>
 <div className="grc-aibrief__actions">
 <Button label="View Evidence" variant="secondary" size="sm" icon="document-eye-outline" onClicked={() => run("View Evidence")} />
 <Button label="Explain Why" variant="secondary" size="sm" icon="circle-question-outline" onClicked={() => run("Explain Why")} />
 <Button label="Recommended Actions" variant="primary" size="sm" icon="lightbulb-outline" onClicked={() => run("Recommended Actions")} />
 <Button label="Ask AI" variant="tertiary" size="sm" icon="chat-ai-sparkle-outline" onClicked={() => run("Ask AI")} />
 </div>
 </Card>

 {/* Executive attention */}
 <Card className="grc-hero__attn" title="Executive Attention" icon="triangle-exclamation-outline">
 <div className="grc-attn">
 {ATTENTION.map(a => (
 <div className="grc-attn__row" key={a.label}>
 <span className="grc-attn__left"><StatusPill severity={a.severity} label={a.label} /></span>
 <span className="grc-attn__val">{a.value}</span>
 </div>
 ))}
 <Button label="View Executive Queue →" variant="secondary" size="sm" onClicked={onViewQueue} />
 </div>
 </Card>
 </div>
 );
}
","// Rich KPI & attribute model for the GRC VP Command Center.
// Pure data + light helpers. No React, no backend.

import type { Severity } from "./mockData";

export type KpiUnit = "%" | "score" | "count" | "days" | "SAR";
export type TrendDir = "up" | "down" | "flat";
export type RiskLevel = "low" | "moderate" | "elevated" | "high" | "severe";

export interface KpiDef {
 id: string;
 name: string;
 domain: string;
 value: number;
 unit: KpiUnit;
 previousValue: number;
 trendPct: number;
 trendDir: TrendDir;
 target: number;
 warningThreshold: number;
 criticalThreshold: number;
 status: Severity;
 riskLevel: RiskLevel;
 owner: string;
 businessUnit: string;
 entity: string;
 period: string;
 sourceDomain: string;
 sourceRecords: number;
 lastUpdated: string;
 confidence: number; // 0-100
 drilldownDimensions: string[];
 relatedRisks: string[];
 relatedControls: string[];
 relatedPolicies: string[];
 relatedRegulations: string[];
 relatedIssues: string[];
 relatedRemediations: string[];
 relatedAssurance: string[];
 series12m: number[]; // 12 monthly points
 definition: string;
 calculation: string;
 whatItMeans: string;
 higherIsBetter: boolean;
 tab: string;
}

type KpiSeed = Partial<KpiDef> &
 Pick<KpiDef, "id" | "name" | "domain" | "value" | "unit" | "tab">;

// Factory that fills sensible defaults so domain files stay concise.
export function kpi(seed: KpiSeed): KpiDef {
 return {
 previousValue: seed.value,
 trendPct: 0,
 trendDir: "flat",
 target: seed.value,
 warningThreshold: seed.value,
 criticalThreshold: seed.value,
 status: "neutral",
 riskLevel: "moderate",
 owner: "GRC Office",
 businessUnit: "All Business Units",
 entity: "Saudi Energy Group",
 period: "Last 90 Days",
 sourceDomain: seed.domain,
 sourceRecords: 0,
 lastUpdated: "2 hours ago",
 confidence: 90,
 drilldownDimensions: [],
 relatedRisks: [],
 relatedControls: [],
 relatedPolicies: [],
 relatedRegulations: [],
 relatedIssues: [],
 relatedRemediations: [],
 relatedAssurance: [],
 series12m: [],
 definition: "",
 calculation: "",
 whatItMeans: "",
 higherIsBetter: true,
 ...seed
 };
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
export const SERIES_LABELS = MONTHS;

export function formatKpiValue(k: Pick<KpiDef, "value" | "unit">): string {
 switch (k.unit) {
 case "%":
 return `${k.value}%`;
 case "score":
 return `${k.value}/100`;
 case "days":
 return `${k.value} days`;
 case "SAR":
 return `SAR ${k.value}M`;
 default:
 return `${k.value}`;
 }
}

export const RISK_LEVEL_SEVERITY: Record<RiskLevel, Severity> = {
 low: "healthy",
 moderate: "info",
 elevated: "watch",
 high: "high",
 severe: "critical"
};
