import { REMEDIATION_KPIS } from "./remediation";

export const ALL_KPIS: KpiDef[] = [
 ...RISK_KPIS,
 ...CONTROL_KPIS,
 ...REGULATORY_KPIS,
 ...GOVERNANCE_KPIS,
 ...INTERNAL_KPIS,
 ...ASSURANCE_KPIS,
 ...REMEDIATION_KPIS
];

const KPI_INDEX: Record<string, KpiDef> = ALL_KPIS.reduce((acc, k) => {
 acc[k.id] = k;
 return acc;
}, {} as Record<string, KpiDef>);

export function getKpi(id: string): KpiDef | undefined {
 return KPI_INDEX[id];
}

export function kpisForTab(tab: string): KpiDef[] {
 return ALL_KPIS.filter(k => k.tab === tab);
}

export function kpisForDomain(domain: string): KpiDef[] {
 return ALL_KPIS.filter(k => k.domain === domain);
}

// The 8 headline KPIs shown in the overview strip (stable ids from Prompt 1).
