","// Business Unit composite scoring.
import { BU_PERFORMANCE, BuPerformance } from "../data/content";

export interface BuComponent {
 key: string;
 label: string;
 value: number;
}

export interface BuScore {
 bu: string;
 overall: number;
 trend: "up" | "down" | "flat";
 rank: number;
 criticalItems: number;
 components: BuComponent[];
 topWeakness: BuComponent;
 topStrength: BuComponent;
}

// Deterministic per-BU remediation + assurance components derived from the record.
function remediationScore(b: BuPerformance): number {
 return Math.round(b.grc * 0.9 + (b.critical > 0 ? -3 : 2));
}
function assuranceScore(b: BuPerformance): number {
 return Math.round(b.grc * 0.95 - b.critical);
}

export function buComponents(b: BuPerformance): BuComponent[] {
 return [
 { key: "risk", label: "Risk Posture", value: b.risk },
 { key: "control", label: "Control Effectiveness", value: b.control },
 { key: "compliance", label: "Compliance", value: b.compliance },
 { key: "governance", label: "Governance", value: b.governance },
 { key: "remediation", label: "Remediation", value: remediationScore(b) },
 { key: "assurance", label: "Assurance Coverage", value: assuranceScore(b) }
 ];
}

// Ranked map of all BU scores (rank 1 = strongest overall).
const RANKED: Record<string, number> = [...BU_PERFORMANCE]
 .sort((a, b) => b.grc - a.grc)
 .reduce((acc, b, i) => {
 acc[b.bu] = i + 1;
 return acc;
 }, {} as Record<string, number>);

export function businessUnitScore(bu: string): BuScore | undefined {
 const b = BU_PERFORMANCE.find(x => x.bu === bu);
 if (!b) return undefined;
 const components = buComponents(b);
 const sorted = [...components].sort((x, y) => x.value - y.value);
 return {
 bu: b.bu,
 overall: b.grc,
 trend: b.trend,
 rank: RANKED[b.bu],
 criticalItems: b.critical,
 components,
 topWeakness: sorted[0],
 topStrength: sorted[sorted.length - 1]
 };
}

export function allBusinessUnitScores(): BuScore[] {
 return BU_PERFORMANCE.map(b => businessUnitScore(b.bu)!).sort((a, b) => a.rank - b.rank);
}
