","// Time-based analytics over numeric series.
import type { TrendDir } from "../data/kpiModel";

export type PeriodBucket = "current" | "7d" | "30d" | "quarter" | "YTD" | "12-month";

// How many trailing points each bucket covers of a 12-month monthly series.
const BUCKET_POINTS: Record<PeriodBucket, number> = {
 current: 1,
 "7d": 2,
 "30d": 2,
 quarter: 3,
 YTD: 9,
 "12-month": 12
};

export function sliceByPeriod(series: number[], period: PeriodBucket): number[] {
 const n = BUCKET_POINTS[period] ?? series.length;
 return series.slice(Math.max(0, series.length - n));
}

export function changePct(series: number[]): number {
 if (series.length < 2) return 0;
 const first = series[0];
 const last = series[series.length - 1];
 if (first === 0) return 0;
 return +(((last - first) / Math.abs(first)) * 100).toFixed(1);
}

export function trendDir(series: number[], eps = 0.5): TrendDir {
 const pct = changePct(series);
 if (pct > eps) return "up";
 if (pct < -eps) return "down";
 return "flat";
}

// Acceleration: is the rate of change itself growing? (2nd difference, averaged)
export function acceleration(series: number[]): number {
 if (series.length < 3) return 0;
 const diffs = series.slice(1).map((v, i) => v - series[i]);
 const secondDiffs = diffs.slice(1).map((d, i) => d - diffs[i]);
 const avg = secondDiffs.reduce((a, b) => a + b, 0) / secondDiffs.length;
 return +avg.toFixed(2);
}

// Volatility: standard deviation of period-over-period change.
export function volatility(series: number[]): number {
 if (series.length < 2) return 0;
 const diffs = series.slice(1).map((v, i) => v - series[i]);
 const mean = diffs.reduce((a, b) => a + b, 0) / diffs.length;
 const variance = diffs.reduce((a, d) => a + (d - mean) ** 2, 0) / diffs.length;
 return +Math.sqrt(variance).toFixed(2);
}

// Simple linear forecast of the next value from the average recent slope.
export function forecastNext(series: number[]): number {
 if (series.length < 2) return series[series.length - 1] ?? 0;
 const window = series.slice(Math.max(0, series.length - 4));
 const slopes = window.slice(1).map((v, i) => v - window[i]);
 const avgSlope = slopes.reduce((a, b) => a + b, 0) / slopes.length;
 return +(series[series.length - 1] + avgSlope).toFixed(2);
}

// Days until a series crosses a threshold at its current slope (per month → days).
export function breachProjectionDays(series: number[], threshold: number): number | null {
 if (series.length < 2) return null;
 const last = series[series.length - 1];
 const slope = last - series[series.length - 2]; // per month
 if (slope === 0) return null;
 const monthsToBreach = (threshold - last) / slope;
 if (monthsToBreach <= 0) return 0;
 return Math.round(monthsToBreach * 30);
}

export interface SeriesAnalytics {
 changePct: number;
 trendDir: TrendDir;
 acceleration: number;
 volatility: number;
 forecastNext: number;
}

export function analyzeSeries(series: number[], period: PeriodBucket = "12-month"): SeriesAnalytics {
 const s = sliceByPeriod(series, period);
 return {
 changePct: changePct(s),
 trendDir: trendDir(s),
 acceleration: acceleration(s),
 volatility: volatility(s),
 forecastNext: forecastNext(series)
 };
}
